#!/usr/bin/env bun

// Generated before `bun build --compile`; it registers static file bytes on
// globalThis so the daemon can serve Fleet UI and public samples when no
// external public/ directory is present.
// @ts-ignore generated by scripts/build-single-binary.mjs before bundle compile.
import '../dist/embedded-public-assets.generated.js';
// @ts-ignore generated by scripts/build-single-binary.mjs before bundle compile.
import '../dist/embedded-native-core.generated.js';
import {
  resolveDbIntegrityHelperInvocation,
  runDbIntegrityHelper,
} from '../lib/db-integrity-entrypoint.js';

process.env.PORT_DADDY_CAN_SELF_DAEMON = '1';

const dbIntegrityHelper = resolveDbIntegrityHelperInvocation(process.argv);
if (dbIntegrityHelper) {
  await runDbIntegrityHelper(dbIntegrityHelper);
} else if (process.argv[2] === '__semantic-runtime-check') {
  const { ensureOnnxRuntimeNativeLibFindable } = await import('../lib/semantic-resolver.js');
  ensureOnnxRuntimeNativeLibFindable();
  const runtime = await import('onnxruntime-node');
  const backends = typeof runtime.listSupportedBackends === 'function'
    ? runtime.listSupportedBackends()
    : [];
  process.stdout.write(`${JSON.stringify({ success: true, backends })}\n`);
} else {
  try {
    const koffi = await import('koffi');
    globalThis.__PORT_DADDY_KOFFI__ = koffi.default ?? koffi;
  } catch (err) {
    globalThis.__PORT_DADDY_KOFFI_LOAD_ERROR__ = (err as Error).message;
  }

  // Homebrew's launchd service historically invokes `pd start --foreground`.
  // Treat that supervised shape exactly like the hidden daemon entrypoint here,
  // before importing the enormous CLI command graph. Importing every CLI command
  // delayed the first daemon heartbeat long enough for Bosun to classify the
  // previous generation as dead and kickstart this new generation in a loop.
  const isHiddenDaemonEntrypoint = process.argv[2] === '__daemon';
  const isSupervisedForegroundStart = process.argv[2] === 'start' && process.argv.includes('--foreground');
  if (isHiddenDaemonEntrypoint || isSupervisedForegroundStart) {
    if (isHiddenDaemonEntrypoint) {
      process.argv = [process.argv[0], process.argv[1], ...process.argv.slice(3)];
    }
    await import('../server.js');
  } else {
    process.env.PORT_DADDY_SUPPRESS_CLI_MAIN = '1';
    // @ts-ignore Bun must import the TS source here; port-daddy-cli.js is the npm shim and would recurse.
    const cli = await import('./port-daddy-cli.ts');
    await cli.main();
  }
}
